template <class T>
bool representable(long double v)
{
   return std::abs(v) <= (std::numeric_limits<T>::max)() && (v == 0 || std::abs(v) >= (std::numeric_limits<T>::min)());
}

// The condition numbers |x f'(x)/f(x)| of the row's functions, from the reference values: with
// s = 1 + xi (x - mu)/sigma and t = -logcdf, d(log t)/dx = -1/(sigma s).
struct cdf_conditions
{
   long double pdf, logpdf, cdf, ccdf, logcdf, logccdf;
};

inline cdf_conditions conditions(long double const (&r)[10])
{
   long double mu = r[0], sigma = r[1], xi = r[2], x = r[3];
   long double s = 1 + xi * (x - mu) / sigma, t = -r[8], P = r[6], Q = r[7];
   long double g = std::abs(x / (sigma * s));
   cdf_conditions c;
   c.pdf = g * std::abs(1 + xi - t);
   c.logpdf = c.pdf / std::abs(r[5]);
   c.cdf = g * t;
   c.ccdf = c.cdf * P / Q;
   c.logcdf = g;
   c.logccdf = c.ccdf / std::abs(r[9]);
   return c;
}

template <class T>
void test_cdf()
{
   // 16 ulps times each function's condition number, which is large deep in the tails (38 for the cdf at
   // xi = 0.3, x = -3, where t = 12); the condition numbers come from the long double references.
   auto ulps = [](long double kappa) { return static_cast<unsigned>(16 * (std::max)(1.0L, kappa)); };
   for (auto const& r : cdf_data)
   {
      generalized_extreme_value_distribution<T> d(static_cast<T>(r[0]), static_cast<T>(r[1]), static_cast<T>(r[2]));
      T x = static_cast<T>(r[3]);
      if (static_cast<long double>(x) != r[3] || static_cast<long double>(d.shape()) != r[2])
      {
         continue;
      }
      cdf_conditions k = conditions(r);
      if (representable<T>(r[4])) { CHECK_ULP_CLOSE(static_cast<T>(r[4]), pdf(d, x), ulps(k.pdf)); }
      CHECK_ULP_CLOSE(static_cast<T>(r[5]), logpdf(d, x), ulps(k.logpdf));
      if (representable<T>(r[6])) { CHECK_ULP_CLOSE(static_cast<T>(r[6]), cdf(d, x), ulps(k.cdf)); }
      if (representable<T>(r[7])) { CHECK_ULP_CLOSE(static_cast<T>(r[7]), cdf(complement(d, x)), ulps(k.ccdf)); }
      if (representable<T>(r[8])) { CHECK_ULP_CLOSE(static_cast<T>(r[8]), logcdf(d, x), ulps(k.logcdf)); }
      if (representable<T>(r[9])) { CHECK_ULP_CLOSE(static_cast<T>(r[9]), logcdf(complement(d, x)), ulps(k.logccdf)); }
   }
}

template <class T>
void test_quantile()
{
   for (auto const& r : quantile_data)
   {
      generalized_extreme_value_distribution<T> d(static_cast<T>(r[0]), static_cast<T>(r[1]), static_cast<T>(r[2]));
      T p = static_cast<T>(r[3]);
      if (static_cast<long double>(p) != r[3] || static_cast<long double>(d.shape()) != r[2])
      {
         continue;
      }
      // mu + sigma q cancels where the quantile is near 0, multiplying the error by (|mu| + |x - mu|)/|x|:
      for (int c = 0; c < 2; ++c)
      {
         long double x = r[4 + c];
         if (!representable<T>(x))
         {
            continue;
         }
         double cancellation = static_cast<double>((std::abs(r[0]) + std::abs(x - r[0])) / std::abs(x));
         double scale = (std::max)(1.0, cancellation);
#if defined(__MINGW32__) || defined(__CYGWIN__)
         // MinGW's long double pow loses about |log x| ulps for huge results:
         if (std::numeric_limits<T>::digits > 53)
         {
            scale = (std::max)(scale, static_cast<double>(std::abs(std::log(std::abs(x)))));
         }
#endif
         unsigned ulps = static_cast<unsigned>(16 * scale);
         CHECK_ULP_CLOSE(static_cast<T>(x), c ? quantile(complement(d, p)) : quantile(d, p), ulps);
      }
   }
}

template <class T>
void test_moments()
{
   const T eps = std::numeric_limits<T>::epsilon();
   for (auto const& r : moment_data)
   {
      T xi = static_cast<T>(r[0]);
      if (static_cast<long double>(xi) != r[0])
      {
         continue;
      }
      generalized_extreme_value_distribution<T> d(T(0.5), T(2), xi);
      CHECK_ULP_CLOSE(static_cast<T>(r[1]), mean(d), 8);
      // Gamma(1 - xi)^2 doubles tgamma's error:
      CHECK_ULP_CLOSE(static_cast<T>(r[2]), variance(d), 32);
      CHECK_ULP_CLOSE(static_cast<T>(r[2]), standard_deviation(d) * standard_deviation(d), 32);
      CHECK_MOLLIFIED_CLOSE(static_cast<T>(r[3]), skewness(d), 64 * eps);
      CHECK_MOLLIFIED_CLOSE(static_cast<T>(r[4]), kurtosis_excess(d), 512 * eps);
      CHECK_MOLLIFIED_CLOSE(static_cast<T>(r[4] + 3), kurtosis(d), 512 * eps);
      CHECK_ULP_CLOSE(static_cast<T>(r[5]), mode(d), 8);
      CHECK_ULP_CLOSE(static_cast<T>(r[6]), median(d), 8);
      CHECK_ULP_CLOSE(static_cast<T>(r[7]), entropy(d), 8);
   }
}

// The support, its endpoints, the moments' domains, and xi = 0 against extreme_value_distribution.
template <class T>
void test_edges()
{
   using boost::math::extreme_value_distribution;
   const T inf = std::numeric_limits<T>::infinity();
   generalized_extreme_value_distribution<T> frechet(T(0.5), T(2), T(0.25));
   generalized_extreme_value_distribution<T> weibull(T(0.5), T(2), T(-0.25));
   // mu - sigma/xi:
   CHECK_EQUAL(support(frechet).first, T(-7.5));
   CHECK_EQUAL(support(weibull).second, T(8.5));
   CHECK_EQUAL(cdf(frechet, T(-7.5)), T(0));
   CHECK_EQUAL(cdf(frechet, T(-100)), T(0));
   CHECK_EQUAL(cdf(complement(frechet, T(-100))), T(1));
   CHECK_EQUAL(pdf(frechet, T(-7.5)), T(0));
   CHECK_EQUAL(logcdf(frechet, T(-100)), -inf);
   CHECK_EQUAL(cdf(weibull, T(8.5)), T(1));
   CHECK_EQUAL(cdf(weibull, T(100)), T(1));
   CHECK_EQUAL(cdf(complement(weibull, T(100))), T(0));
   CHECK_EQUAL(pdf(weibull, T(8.5)), T(0));
   CHECK_EQUAL(logpdf(weibull, T(100)), -inf);
   CHECK_EQUAL(quantile(frechet, T(0)), T(-7.5));
   CHECK_EQUAL(quantile(complement(weibull, T(0))), T(8.5));
   CHECK_EQUAL(cdf(frechet, inf), T(1));
   CHECK_EQUAL(cdf(weibull, -inf), T(0));
   CHECK_EQUAL(pdf(frechet, inf), T(0));
   // Just past an end point, where (x - mu)/sigma rounds onto it:
   generalized_extreme_value_distribution<T> unit_end(T(-1), T(1), T(-1));
   CHECK_EQUAL(pdf(unit_end, T(1e-17)), T(0));
   CHECK_EQUAL(logpdf(unit_end, T(1e-17)), -inf);
   CHECK_EQUAL(cdf(unit_end, T(1e-17)), T(1));
   // log(1 - cdf) = -L once t = exp(-L) underflows:
   generalized_extreme_value_distribution<T> gumbel(T(0), T(1), T(0));
   if (std::numeric_limits<T>::max_exponent10 < 300)
   {
      CHECK_ULP_CLOSE(T(-100), logcdf(complement(gumbel, T(100))), 1);
   }
   else
   {
      CHECK_ULP_CLOSE(T(-750), logcdf(complement(gumbel, T(750))), 1);
   }
   // At the upper endpoint the density is t^(1 + xi)/sigma with t = 0:
   CHECK_EQUAL(pdf(generalized_extreme_value_distribution<T>(T(0), T(2), T(-1)), T(2)), T(0.5));
   CHECK_THROW(pdf(generalized_extreme_value_distribution<T>(T(0), T(2), T(-2)), T(1)), std::overflow_error);
   // Unbounded ends:
   CHECK_THROW(quantile(frechet, T(1)), std::overflow_error);
   CHECK_THROW(quantile(weibull, T(0)), std::overflow_error);
   // Moments that do not exist:
   generalized_extreme_value_distribution<T> heavy(T(0), T(1), T(1));
   // The mean and variance are infinite there, the skewness and kurtosis undefined:
   CHECK_EQUAL(mean(heavy), inf);
   CHECK_EQUAL(variance(generalized_extreme_value_distribution<T>(T(0), T(1), T(0.5))), inf);
   CHECK_EQUAL(standard_deviation(heavy), inf);
   CHECK_THROW(skewness(generalized_extreme_value_distribution<T>(T(0), T(1), T(1) / 3)), std::domain_error);
   CHECK_THROW(kurtosis(generalized_extreme_value_distribution<T>(T(0), T(1), T(0.25))), std::domain_error);
   CHECK_THROW(generalized_extreme_value_distribution<T>(T(0), T(0), T(0)), std::domain_error);
   CHECK_THROW(generalized_extreme_value_distribution<T>(T(0), T(1), inf), std::domain_error);
   check_out_of_range<generalized_extreme_value_distribution<T>>(T(0.5), T(2), T(0.25));
   check_out_of_range<generalized_extreme_value_distribution<T>>(T(0.5), T(2), T(-0.25));

   // xi = 0 is the Gumbel distribution, and tiny xi tends to it; two implementations, deep in the tail at x = 30:
   generalized_extreme_value_distribution<T> g(T(0.5), T(2), T(0));
   extreme_value_distribution<T> e(T(0.5), T(2));
   for (T x : { T(-3), T(0.5), T(4), T(30) })
   {
      CHECK_ULP_CLOSE(pdf(e, x), pdf(g, x), 16);
      CHECK_ULP_CLOSE(cdf(e, x), cdf(g, x), 4);
      CHECK_ULP_CLOSE(cdf(complement(e, x)), cdf(complement(g, x)), 4);
   }
   for (T p : { T(0.001), T(0.5), T(0.999) })
   {
      CHECK_ULP_CLOSE(quantile(e, p), quantile(g, p), 4);
   }
   CHECK_ULP_CLOSE(skewness(e), skewness(g), 0);
   CHECK_ULP_CLOSE(kurtosis(e), kurtosis(g), 0);
   generalized_extreme_value_distribution<T> tiny(T(0.5), T(2), std::numeric_limits<T>::denorm_min());
   CHECK_ULP_CLOSE(mean(e), mean(tiny), 1);
   CHECK_ULP_CLOSE(cdf(e, T(4)), cdf(tiny, T(4)), 4);
   CHECK_ULP_CLOSE(quantile(e, T(0.25)), quantile(tiny, T(0.25)), 4);
}

#ifdef BOOST_MATH_TEST_GEV_MULTIPRECISION
// The moment series in many digits, against the closed forms in more, and the quantile's round trip
// (away from p -> 0, where cdf(quantile(p)) multiplies the error by -log p).
void test_multiprecision()
{
   using T = boost::multiprecision::cpp_bin_float_50;
   using U = boost::multiprecision::cpp_bin_float_100;
   for (const char* s : { "-0.1", "-1e-10", "1e-10", "0.0625", "0.15", "0.2" })
   {
      T xi(s);
      U k(xi);
      generalized_extreme_value_distribution<T> d(T(0), T(1), xi);
      U g1 = boost::math::tgamma(1 - k), g2 = boost::math::tgamma(1 - 2 * k), g3 = boost::math::tgamma(1 - 3 * k), g4 = boost::math::tgamma(1 - 4 * k);
      U var = (g2 - g1 * g1) / (k * k);
      U skew = (k > 0 ? 1 : -1) * (g3 - 3 * g1 * g2 + 2 * g1 * g1 * g1) / pow(g2 - g1 * g1, U(1.5));
      U kex = (g4 - 4 * g1 * g3 + 6 * g2 * g1 * g1 - 3 * g1 * g1 * g1 * g1) / ((g2 - g1 * g1) * (g2 - g1 * g1)) - 3;
      // tgamma itself is ~20 ulps at 50 digits, and the variance has Gamma(1 - xi)^2:
      CHECK_ULP_CLOSE(T(var), variance(d), 128);
      CHECK_MOLLIFIED_CLOSE(T(skew), skewness(d), T(64 * std::numeric_limits<T>::epsilon()));
      CHECK_MOLLIFIED_CLOSE(T(kex), kurtosis_excess(d), T(512 * std::numeric_limits<T>::epsilon()));
      for (T p : { T(0.001), T(0.3), T(0.9) })
      {
         CHECK_ULP_CLOSE(p, cdf(d, quantile(d, p)), 64);
      }
   }
}
#endif

int main()
{
   test_cdf<float>();
   test_cdf<double>();
   test_cdf<long double>();
   test_quantile<float>();
   test_quantile<double>();
   test_quantile<long double>();
   test_moments<float>();
   test_moments<double>();
   test_moments<long double>();
   test_edges<float>();
   test_edges<double>();
   test_edges<long double>();
#ifdef BOOST_MATH_TEST_GEV_MULTIPRECISION
   test_multiprecision();
#endif
   return boost::math::test::report_errors();
}
